# generate unique orientations of mask and stamps at zero positions, non-overlap? 
forms=[]
base=np.zeros((H,W),int);base[m[:,0],m[:,1]]=1
for k in range(4):
 a=np.rot90(base,k)
 for b in [a,np.fliplr(a)]:
  if not any(np.array_equal(b,x) for x in forms): forms.append(b)
print([x.shape for x in forms])

from collections import deque
# floodfill zeros connected 4-neighbor to any seed 2
out=g.copy(); q=deque(map(tuple,mask)); seen=set(map(tuple,mask))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  rr,cc=r+dr,c+dc
  if 0<=rr<19 and 0<=cc<15 and out[rr,cc]==0 and (rr,cc) not in seen:
   seen.add((rr,cc));out[rr,cc]=2;q.append((rr,cc))
print(len(seen)); print('\n'.join(''.join(map(str,row)) for row in out))

